/* Only the wrapped libc functions are visible; the bundled C++ runtime stays private so it can
   never interpose on the guest's own libc++ / operator new. */
{
  global:
    open; open64; openat; openat64; __open_2; __openat_2;
    stat; stat64; lstat; lstat64; fstatat; fstatat64; fstat; fstat64;
    access; faccessat; readlink; readlinkat;
    mkdir; mkdirat; unlink; unlinkat; rmdir;
    chmod; fchmodat; fchmod; rename; renameat;
    ioctl; mmap; mmap64; close; syscall;
    socket; bind; connect; getsockname; setsockopt; send; sendto; sendmsg; write; writev; recvfrom; recvmsg;
    minijail_use_seccomp_filter;
    extern "C++" { "set_app_seccomp_filter()"; "set_app_zygote_seccomp_filter()"; "set_system_seccomp_filter()"; "install_setuidgid_seccomp_filter(unsigned int, unsigned int)"; };
  local: *;
};
